package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles full-text search with filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	userID := r.Header.Get("X-Authenticated-User-ID")
	if userID == "" {
		http.Error(w, "Unauthorized", 401)
		return
	}

	query := r.URL.Query().Get("q")
	classification := r.URL.Query().Get("level")
	sortField := r.URL.Query().Get("sort")

	// Build base query with user's access scope
	baseSQL := fmt.Sprintf(
		"SELECT id, title, content, owner_id, classification FROM documents WHERE owner_id = %s",
		userID,
	)

	// Add search filter
	if query != "" {
		// Using to_tsquery for full-text search - parameterized
		baseSQL += " AND tsv @@ plainto_tsquery('english', $1)"
	}

	// Add classification filter
	if classification != "" {
		// Validated against known values
		validLevels := map[string]bool{"public": true, "internal": true, "confidential": true, "secret": true}
		if !validLevels[strings.ToLower(classification)] {
			http.Error(w, "Invalid classification level", 400)
			return
		}
		baseSQL += fmt.Sprintf(" AND classification = '%s'", strings.ToLower(classification))
	}

	// Add sorting - THIS IS THE VULNERABILITY
	// Developer assumed sort field is safe because it's "just a column name"
	if sortField != "" {
		baseSQL += " ORDER BY " + sortField
	} else {
		baseSQL += " ORDER BY id DESC"
	}

	baseSQL += " LIMIT 50"

	var rows *sql.Rows
	var err error

	if query != "" {
		rows, err = db.Query(baseSQL, query)
	} else {
		rows, err = db.Query(baseSQL)
	}

	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// healthCheck for LB probes
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/documents/search", searchDocuments)
	http.HandleFunc("/healthz", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
